package io.github.jesterportfolio.hearth.gathering;

import io.github.jesterportfolio.hearth.persistence.PostgresProgressStore;
import io.github.jesterportfolio.hearth.lifecycle.WorldLifecycle;
import io.github.jesterportfolio.hearth.session.*;
import org.bukkit.*;
import org.bukkit.block.TileState;
import org.bukkit.plugin.java.JavaPlugin;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import com.sk89q.worldguard.WorldGuard;
import com.sk89q.worldedit.bukkit.BukkitAdapter;
import com.sk89q.worldedit.math.BlockVector3;
import com.sk89q.worldguard.protection.flags.*;
import com.sk89q.worldguard.protection.regions.ProtectedCuboidRegion;

/** 제작자 지정 최대 4096블록만 초기화합니다. 저장된 before 이미지 외 자동 복원/삭제는 하지 않습니다. */
public final class PaperGatheringArea implements GatheringDungeon.Boundary {
    public interface People {CompletionStage<Void> save(List<GatheringDungeon.Member> members);CompletionStage<Void> evacuate(List<GatheringDungeon.Member> members,BooleanSupplier valid);CompletionStage<Boolean> enter(GatheringDungeon.Member member,long generation,BooleanSupplier valid);void notice(String text);default void release(){}}
    private final JavaPlugin plugin;private final PostgresProgressStore db;private final WorldLifecycle world;private final GatheringContent content;private final People people;private final Executor owner;private final long generation;private boolean virgin;private final Path folder,marker;private final Map<Chunk,Boolean> tickets=new HashMap<>();
    public PaperGatheringArea(JavaPlugin plugin,PostgresProgressStore db,WorldLifecycle world,GatheringContent content,People people,Executor owner,boolean virgin)throws Exception{
        if(!plugin.getConfig().getBoolean("gathering-verification-enabled")||!Boolean.getBoolean("hearth.verification.gathering"))throw new IllegalStateException("GATHERING_ISOLATED_GATE");this.plugin=plugin;this.db=db;this.world=world;this.content=content;this.people=people;this.owner=owner;this.virgin=virgin;generation=world.generation();folder=plugin.getDataFolder().toPath().resolve("gathering").resolve(world.mapping().storyRunId()+"_"+content.id());Files.createDirectories(folder);if(!folder.toRealPath().equals(folder.toAbsolutePath().normalize()))throw new IllegalStateException("GATHERING_PATH");marker=folder.resolve("pending.properties");if(Files.exists(marker,LinkOption.NOFOLLOW_LINKS))throw new IllegalStateException("GATHERING_PENDING_REVIEW");
        var w=Objects.requireNonNull(Bukkit.getWorld(world.mapping().physicalId()));var manager=Objects.requireNonNull(WorldGuard.getInstance().getPlatform().getRegionContainer().get(BukkitAdapter.adapt(w)));var a=content.area();String id="hearth_gather_"+content.id();var min=BlockVector3.at(a.x(),a.y(),a.z());var max=BlockVector3.at(a.x()+a.width()-1,a.y()+a.height()-1,a.z()+a.depth()-1);var old=manager.getRegion(id);if(old==null){var region=new ProtectedCuboidRegion(id,min,max);region.setPriority(30);region.setFlag(Flags.BUILD,StateFlag.State.ALLOW);manager.addRegion(region);}else if(!old.getMinimumPoint().equals(min)||!old.getMaximumPoint().equals(max)||old.getPriority()!=30||old.getFlag(Flags.BUILD)!=StateFlag.State.ALLOW)throw new IllegalStateException("GATHERING_REGION_CONFLICT");
    }
    public boolean current(){return world.generation()==generation&&Bukkit.getWorld(world.mapping().physicalId())!=null;}
    public void notice(String message){people.notice(message);}public CompletionStage<Void> save(List<GatheringDungeon.Member> members){return people.save(members);}public CompletionStage<Void> evacuate(List<GatheringDungeon.Member> members,BooleanSupplier valid){return people.evacuate(members,valid);}public CompletionStage<Boolean> enter(GatheringDungeon.Member member,long gen,BooleanSupplier valid){return people.enter(member,gen,valid);}
    private <T> CompletionStage<T> safe(Supplier<T> action){long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(30);var result=new CompletableFuture<T>();Bukkit.getScheduler().runTaskLater(plugin,new Runnable(){public void run(){if(result.isDone())return;try{if(System.nanoTime()>=deadline)throw new IllegalStateException("GATHERING_SAFE_TIMEOUT");if(!current())throw new IllegalStateException("GATHERING_STALE_WORLD");if(Bukkit.isTickingWorlds()){Bukkit.getScheduler().runTaskLater(plugin,this,1);return;}result.complete(action.get());}catch(Exception e){result.completeExceptionally(e);}}},1);return result;}
    public CompletionStage<Void> prepare(GatheringContent.Template template,UUID request,BooleanSupplier valid){
        var w=Objects.requireNonNull(Bukkit.getWorld(world.mapping().physicalId()));var chunks=new LinkedHashSet<String>();for(var c:content.area().cells())chunks.add((c.x()>>4)+":"+(c.z()>>4));CompletionStage<Void> work=CompletableFuture.completedFuture(null);for(String key:chunks){var parts=key.split(":");work=work.thenComposeAsync(v->w.getChunkAtAsync(Integer.parseInt(parts[0]),Integer.parseInt(parts[1])).thenAcceptAsync(chunk->{if(!valid.getAsBoolean())throw new IllegalStateException("GATHERING_STALE");if(!tickets.containsKey(chunk))tickets.put(chunk,chunk.addPluginChunkTicket(plugin));},owner),owner);}
        return work.thenComposeAsync(v->safe(()->{if(!valid.getAsBoolean())throw new IllegalStateException("GATHERING_STALE");var before=new Properties();before.setProperty("run",world.mapping().storyRunId().toString());before.setProperty("world",w.getUID().toString());before.setProperty("request",request.toString());before.setProperty("target",template.version()+"/"+template.hash());for(var c:content.area().cells()){var b=w.getBlockAt(c.x(),c.y(),c.z());if(virgin&&!b.isEmpty())throw new IllegalStateException("GATHERING_UNOWNED_BLOCKS");if(b.getState() instanceof TileState)throw new IllegalStateException("GATHERING_UNSUPPORTED_CONTAINER");before.setProperty(c.x()+","+c.y()+","+c.z(),b.getBlockData().getAsString());}return before;}),owner).thenCompose(before->db.module("gathering_before_image",c->{if(Files.exists(marker,LinkOption.NOFOLLOW_LINKS))throw new IllegalStateException("GATHERING_PENDING_REVIEW");try(var out=Files.newOutputStream(folder.resolve(request+"-before.properties"),StandardOpenOption.CREATE_NEW)){before.store(out,"제한 구역 원본 · 관리자 확인용");}try(var out=Files.newOutputStream(marker,StandardOpenOption.CREATE_NEW)){before.store(out,"초기화 확인 전 입장 금지");}return null;}));
    }
    public CompletionStage<Void> apply(GatheringContent.Template template,BooleanSupplier valid){var cells=content.area().cells();var done=new CompletableFuture<Void>();Bukkit.getScheduler().runTaskLater(plugin,new Runnable(){int offset;public void run(){if(done.isDone())return;try{if(!current()||!valid.getAsBoolean())throw new IllegalStateException("GATHERING_STALE");if(Bukkit.isTickingWorlds()){Bukkit.getScheduler().runTaskLater(plugin,this,1);return;}var w=Objects.requireNonNull(Bukkit.getWorld(world.mapping().physicalId()));if(w.getPlayers().stream().anyMatch(p->content.area().contains(p.getX(),p.getY(),p.getZ())))throw new IllegalStateException("GATHERING_PLAYERS_NOT_EVACUATED");int end=Math.min(cells.size(),offset+64);while(offset<end){var c=cells.get(offset++);w.getBlockAt(c.x(),c.y(),c.z()).setType(Material.valueOf(template.blocks().get(c)),false);}if(offset==cells.size())done.complete(null);else Bukkit.getScheduler().runTaskLater(plugin,this,1);}catch(Exception e){done.completeExceptionally(e);}}},1);return done;}
    public CompletionStage<Void> flush(){return safe(()->{var w=Objects.requireNonNull(Bukkit.getWorld(world.mapping().physicalId()));var manager=Objects.requireNonNull(WorldGuard.getInstance().getPlatform().getRegionContainer().get(BukkitAdapter.adapt(w)));return manager;}).thenCompose(manager->db.module("gathering_regions_save",c->{manager.save();return null;})).thenComposeAsync(v->safe(()->{Bukkit.getWorld(world.mapping().physicalId()).save(true);return null;}),owner);}
    public void release(){people.release();for(var e:tickets.entrySet())if(e.getValue())e.getKey().removePluginChunkTicket(plugin);tickets.clear();}
    public CompletionStage<Void> acknowledge(UUID request){return db.module("gathering_ack",c->{var p=new Properties();try(var in=Files.newInputStream(marker)){p.load(in);}if(!request.toString().equals(p.getProperty("request"))||!world.mapping().storyRunId().toString().equals(p.getProperty("run")))throw new IllegalStateException("GATHERING_MARKER_OWNER");Files.delete(marker);return null;}).thenRunAsync(()->virgin=false,owner);}
}
